const fs = require('fs');
const https = require('https');

// Read the .env.test file
const envContent = fs.readFileSync('./.env.test', 'utf8');

// Parse environment variables
const envVars = {};
const lines = envContent.split('\n');

lines.forEach(line => {
    // Skip comments and empty lines
    if (line.trim() && !line.startsWith('#')) {
        const [key, value] = line.split('=');
        if (key && value) {
            envVars[key.trim()] = value.trim();
        }
    }
});

// Create JSON payload
const payload = JSON.stringify({
    environment: 'test',
    variables: envVars,
    timestamp: new Date().toISOString(),
    source: '.env.test'
});

console.log('Extracted environment variables:', envVars);

// Make POST request to the documentation endpoint
const options = {
    hostname: 'localhost',
    port: 3003,
    path: '/api/doc-export',
    method: 'POST',
    headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(payload)
    }
};

const req = https.request(options, (res) => {
    console.log(`Status Code: ${res.statusCode}`);

    let responseData = '';
    res.on('data', (chunk) => {
        responseData += chunk;
    });

    res.on('end', () => {
        console.log('Response:', responseData);
        console.log('Environment variables successfully exported to documentation wiki.');
    });
});

req.on('error', (error) => {
    console.error('Error making request:', error.message);
    console.log('Payload that would have been sent:');
    console.log(payload);
});

// Write the payload and end the request
req.write(payload);
req.end();

